import ghidra.app.decompiler.*; import ghidra.app.script.GhidraScript; import ghidra.program.model.address.*; import ghidra.program.model.listing.*; import ghidra.program.model.mem.*;
public class SweepScalar2 extends GhidraScript { public void run()throws Exception{Address a=toAddr(0x004d6560L);println("DATA "+getDataAt(a));println("BYTES");for(int i=0;i<32;i++)println(String.format("%08x %02x",0x004d6560+i,getByte(a.add(i))&255));Function f=getFunctionContaining(a);println("FUNC "+f);if(f!=null){DecompInterface d=new DecompInterface();d.openProgram(currentProgram);println(d.decompileFunction(f,500,monitor).getDecompiledFunction().getC());}d.dispose();}}
